package com.hbm.missile.launchpad.large;
import com.hbm.missile.launchpad.standard.StandardLaunchPadBlock;import com.mojang.serialization.MapCodec;import java.util.List;import net.minecraft.core.BlockPos;import net.minecraft.world.level.*;import net.minecraft.world.level.block.entity.*;import net.minecraft.world.level.block.state.BlockState;import net.minecraft.world.phys.shapes.*;
/** Real nine-by-nine source pad, exact three collision regions and eight outward ports. */
public final class LargeLaunchPadBlock extends StandardLaunchPadBlock{private static final VoxelShape SHAPE=Shapes.or(Shapes.box(-4.5,0,-4.5,4.5,1,-.5),Shapes.box(-4.5,0,.5,4.5,1,4.5),Shapes.box(-4.5,.875,-.5,4.5,1,.5));@Override protected MapCodec<? extends com.hbm.multiblock.DummyableBlock> codec(){return simpleCodec(p->new LargeLaunchPadBlock());}@Override public int[] dimensions(){return new int[]{0,0,4,4,4,4};}@Override public int offset(){return 4;}@Override public BlockEntity newBlockEntity(BlockPos pos,BlockState state){return isCore(state)?new LargeLaunchPadBlockEntity(pos,state):new LargeLaunchPadPort(pos,state);}@Override public <T extends BlockEntity> BlockEntityTicker<T> getTicker(Level level,BlockState state,BlockEntityType<T> type){return isCore(state)?createTickerHelper(type,LargeLaunchPadContent.ENTITY.get(),LargeLaunchPadBlockEntity::tick):null;}@Override protected List<BlockPos> placementPorts(BlockPos core){return LargeLaunchPadBlockEntity.portPositionsLarge(core);}private VoxelShape shape(BlockGetter level,BlockPos pos){var core=findCore(level,pos);return core==null?Shapes.empty():Shapes.join(SHAPE.move(core.getX()-pos.getX()+.5,core.getY()-pos.getY(),core.getZ()-pos.getZ()+.5),Shapes.block(),BooleanOp.AND);}@Override protected VoxelShape getShape(BlockState state,BlockGetter level,BlockPos pos,CollisionContext context){return shape(level,pos);}@Override protected VoxelShape getCollisionShape(BlockState state,BlockGetter level,BlockPos pos,CollisionContext context){return shape(level,pos);}}
